const $=s=>document.querySelector(s);const photo=(id,w=800)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const countries=[{name:'カナダ',x:20.56,y:17.28,img:'photo-1503614472-8c93d56e92ce',text:'山や湖に囲まれた景色と、多様な文化がある街。ホームステイや語学学習から、新しい毎日を想像してみよう。'},{name:'アメリカ',x:22.78,y:29.01,img:'photo-1485738422979-f5c462d49f74',text:'キャンパス、アート、スポーツ。自分の興味をきっかけに、広い世界の一部を体験してみよう。'},{name:'イギリス',x:49.44,y:19.14,img:'photo-1513635269975-59663e0ac1ad',text:'歴史のある街並みと学びの文化。授業も放課後の街歩きも、忘れられない経験に。'},{name:'フィリピン',x:83.89,y:45.06,img:'photo-1518509562904-e7ef99cdcc86',text:'英語を使う毎日と、南国の風景。学習スタイルやサポートを比べて、自分に合う学校を探そう。'},{name:'オーストラリア',x:87.22,y:67.90,img:'photo-1506973035872-a4ec16b8e8d9',text:'青い海、開放的な街、さまざまな文化。英語学習と現地での体験を組み合わせてみよう。'},{name:'ニュージーランド',x:98.06,y:77.78,img:'photo-1469521669194-babb45599def',text:'豊かな自然の中で学び、暮らす。現地校での学校生活や、アウトドアの体験を見つけよう。'}];
const plans=[{id:1,title:'カナダでホームステイ',country:'カナダ',weeks:2,min:45,max:60,ages:['中学生','高校生'],company:'A',theme:['夏休み','はじめて'],desc:'語学レッスンとホームステイを組み合わせた短期留学のサンプル。学校の外でも英語に触れる毎日をイメージできます。'},{id:2,title:'オーストラリアで英語体験',country:'オーストラリア',weeks:2,min:40,max:55,ages:['高校生','大学生'],company:'B',theme:['夏休み','はじめて'],desc:'英語の授業と街での文化体験を組み合わせたサンプルプランです。'},{id:3,title:'イギリスの夏を体験',country:'イギリス',weeks:3,min:60,max:80,ages:['中学生','高校生'],company:'C',theme:['夏休み','はじめて'],desc:'夏休みに語学学習と文化交流を体験する、サマープログラムの掲載例です。'},{id:4,title:'アメリカで英語＋スポーツ',country:'アメリカ',weeks:2,min:55,max:75,ages:['高校生','大学生'],company:'C',theme:['スポーツ','夏休み'],desc:'好きなスポーツを通して海外の仲間と交流する留学のサンプルです。'},{id:5,title:'ニュージーランドの高校へ',country:'ニュージーランド',weeks:8,min:85,max:100,ages:['高校生'],company:'B',theme:['高校'],desc:'現地の高校で授業や学校生活に参加する留学のサンプルです。'},{id:6,title:'フィリピンで英語に集中',country:'フィリピン',weeks:4,min:25,max:40,ages:['高校生','大学生'],company:'A',theme:['はじめて'],desc:'英語の学習時間をしっかり確保したい人に向けた、語学留学の掲載例です。'}];

