const planCategories=[{"id":"language","label":"語学を学ぶ","en":"LANGUAGE","description":"語学学校・語学中心のサマースクール","icon":"◎"},{"id":"school","label":"現地校・大学で学ぶ","en":"SCHOOL","description":"現地の授業・学校生活を体験","icon":"▤"},{"id":"specialty","label":"専門・体験を学ぶ","en":"EXPERIENCE","description":"スポーツなど、好きな分野を深める","icon":"✦"}];
plans.forEach(p=>p.category=p.id===5?'school':p.id===4?'specialty':'language');
