document.querySelector('#map').insertAdjacentHTML('afterend','<div class="country-options" role="group" aria-label="国を選ぶ">'+countries.map(c=>'<button class="country-option" data-country="'+c.name+'" aria-pressed="false">'+c.name+'</button>').join('')+'</div>');
