let saved=[];try{saved=JSON.parse(localStorage.getItem('sorafune-favorites')||'[]');if(!Array.isArray(saved))saved=[]}catch{}let savedOnly=false,theme='',companyFilter='';const modal=$('#modal');function openModal(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal()}$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}function save(id){saved=saved.includes(id)?saved.filter(v=>v!==id):[...saved,id];try{localStorage.setItem('sorafune-favorites',JSON.stringify(saved))}catch{}renderPlans();toast(saved.includes(id)?'気になるプランに保存しました':'保存を解除しました')}
function renderPlans(){document.querySelectorAll("[data-theme]").forEach(b=>{const active=b.dataset.theme===theme;b.classList.toggle("active",active);b.setAttribute("aria-pressed",String(active))});let list=plans.filter(p=>(!$('#age').value||p.ages.includes($('#age').value))&&(!$('#country').value||p.country===$('#country').value)&&(!$('#budget').value||p.max<=Number($('#budget').value))&&(!$('#duration').value||($('#duration').value==='2'?p.weeks<=2:$('#duration').value==='4'?p.weeks>2&&p.weeks<=4:p.weeks>4))&&(!theme||p.category===theme)&&(!companyFilter||p.company===companyFilter)&&(!savedOnly||saved.includes(p.id)));if($('#sort').value==='price')list.sort((a,b)=>a.min-b.min);if($('#sort').value==='duration')list.sort((a,b)=>a.weeks-b.weeks);$('#result-count').textContent=`${savedOnly?'保存したプラン · ':''}${theme?planCategories.find(c=>c.id===theme).label+' · ':''}${companyFilter?'留学会社'+companyFilter+' · ':''}${list.length}件のサンプルプラン`;$('#saved-count').textContent=saved.length;$('#saved-toggle').classList.toggle('saved-on',savedOnly);$('#plan-grid').innerHTML=list.length?list.map(p=>`<article class="plan-card"><div class="plan-photo"><img loading="lazy" src="${photo(countries.find(c=>c.name===p.country).img)}" alt="${p.country}の風景"><button class="save ${saved.includes(p.id)?'selected':''}" data-save="${p.id}" aria-label="${p.title}を${saved.includes(p.id)?'保存解除':'保存'}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button></div><div class="plan-body"><span class="tag">${p.ages.join('・')}</span><h3>${p.title}</h3><div class="plan-meta">${p.country} ｜ ${p.weeks}週間</div><div class="price"><small>概算総額</small>${p.min}〜${p.max}万円</div><p class="provider">取扱会社：留学会社${p.company}（サンプル）</p><div class="card-actions"><button class="button white" data-plan="${p.id}">詳細を見る</button><button class="button orange" data-plan-consult="${p.id}">会社に相談</button></div></div></article>`).join(''):'<div class="empty"><h3>条件に合うプランがありません。</h3><p>国や予算の条件を広げて、もう一度探してみましょう。</p><button class="button white" data-reset>条件をリセット</button></div>'}
function reset(){['age','country','duration','budget'].forEach(id=>$('#'+id).value='');theme='';companyFilter='';savedOnly=false;renderPlans()}$('#reset').onclick=reset;$('#search-form').onsubmit=e=>{e.preventDefault();theme='';companyFilter='';savedOnly=false;renderPlans();$('#plans').scrollIntoView()};$('#sort').onchange=renderPlans;$('#saved-toggle').onclick=()=>{reset();savedOnly=true;renderPlans();$('#plans').scrollIntoView()};
function countrySelect(name){const c=countries.find(v=>v.name===name);document.querySelectorAll('[data-country-shape]').forEach(el=>el.classList.toggle('selected-land',el.dataset.countryShape===name));document.querySelectorAll('.map-pin,.country-option').forEach(p=>{p.classList.toggle('active',p.dataset.country===name);p.setAttribute('aria-pressed',p.dataset.country===name)});$('#country-card').innerHTML=`<img src="${photo(c.img)}" alt="${c.name}の景色"><h3>${c.name}</h3><p>${c.text}</p><button class="button white small" data-country-plans="${c.name}">この国のプランを見る ↗</button>`}$('#pins').innerHTML=countries.map(c=>`<button class="map-pin" style="left:${c.x}%;top:${c.y}%" data-country="${c.name}" aria-pressed="false"><span>${c.name}</span></button>`).join('');countrySelect('カナダ');
function detail(id){const p=plans.find(v=>v.id===id);openModal(`<span class="tag">サンプルプラン</span><h2>${p.title}</h2><p>${p.desc}</p><table><tr><td>対象</td><td>${p.ages.join('・')}</td></tr><tr><td>期間</td><td>${p.weeks}週間</td></tr><tr><td>概算総額の仮例</td><td>${p.min}〜${p.max}万円</td></tr><tr><td>取扱会社</td><td>留学会社${p.company}（架空の掲載例）</td></tr></table><p>この仮例では授業料・滞在費・航空券・保険を含む想定です。現地交通費やおこづかいは別途。出発日、受入条件、実際の料金は未設定です。</p><button class="button orange" data-plan-consult="${id}">このプランについて相談</button>`)}
function consultation(target){openModal(`<span class="eyebrow">FREE CONSULTATION</span><h2>${target==='カウンセラー'?'きみの一歩を、一緒に。':'このプランについて相談'}</h2><p>相談先：${target==='カウンセラー'?'ソラフネのカウンセラー（予定）':target}</p><p class="demo-note">相談窓口は準備中です。この画面は入力体験用です。入力内容は送信・保存されません。実際の個人情報は入力しないでください。</p><form id="consult-form"><label>呼び名<input name="name" placeholder="例：そら" required maxlength="50"></label><label>現在の学年<select><option>中学生</option><option>高校生</option><option>大学生</option><option>保護者</option></select></label><label>相談したいこと<textarea rows="3" placeholder="行き先を一緒に考えたい、費用を知りたい…" required maxlength="1000"></textarea></label><button class="button orange" type="submit">入力内容を確認する</button></form>`);$('#consult-form').onsubmit=e=>{e.preventDefault();openModal('<h2>相談の準備ができました。</h2><p>体験版のため、入力内容は送信・保存していません。正式な相談窓口の公開後にお申し込みいただけます。</p><button class="button navy" data-close>ページに戻る</button>')}}
const articles=[{id:'vlog',type:'Vlog',title:'放課後、何してる？',img:'photo-1523240795612-9a054b0db644',desc:'授業のあとに広がる、もうひとつの留学。',body:'現地の学生の放課後や休日に密着するVlogを制作予定です。実際の動画が公開されると、この場所から視聴できます。'},{id:'home',type:'ガイド',title:'はじめてのホームステイ',img:'photo-1529156069898-49953e39b3ac',desc:'家族との暮らしから、異文化を知る。',body:'到着したら、食事の時間、洗濯、お風呂、外出時の連絡など、家のルールを確認しましょう。分からないことをメモして質問することも大切です。困ったときに相談できる学校や会社の窓口も、出発前に確認しておきましょう。'},{id:'prepare',type:'ガイド',title:'留学までの準備リスト',img:'photo-1488646953014-85cb44e25828',desc:'「行ってみたい」を、少しずつ具体的に。',body:'まずは目的・時期・期間・予算を整理。次に、候補のプランの参加条件と費用の内訳を比較します。学校や保護者とも話し、渡航手続き、滞在先、保険、現地連絡先の確認へ進みましょう。必要な手続きや日程は渡航先・プランによって異なります。'}];
function journal(type='all'){$('#journal-grid').innerHTML=articles.filter(a=>type==='all'||a.type===type).map(a=>`<button class="article-card" data-article="${a.id}"><img loading="lazy" src="${photo(a.img)}" alt="${a.title}のイメージ"><span class="tag">${a.type}${a.type==='Vlog'?'・準備中':''}</span><h3>${a.title}</h3><p>${a.desc}</p></button>`).join('')}
const contents={video:['留学Vlog、公開準備中。','海外で過ごす学生の一日や、ホームステイの様子を届ける予定です。現在の写真はイメージです。'],community:['世界に興味がある。それが共通点。','オンラインで先輩や同世代と交流するコミュニティーを準備しています。留学前の疑問や、英語学習、現地生活を話せる場所を目指します。','参加対象・開催方法・運営スタッフのサポート・利用ルールは、募集開始時にご案内します。現在は参加を受け付けていません。'],event1:['先輩と話す留学座談会','留学を決めたきっかけや、現地で困ったことを先輩に聞くオンラインイベントの企画例です。','開催日・登壇者・参加方法は未定です。受付開始後にこのページでご案内します。'],event2:['親子ではじめる留学準備','費用の見方、準備の順番、現地サポートの確認を親子で考える企画例です。','現在は開催準備中です。申し込みは受け付けていません。'],event3:['カナダの暮らしトーク','学校やホストファミリーとの日々をテーマに、現地の生活を知る企画例です。','開催日・参加費・登壇者は決定後にご案内します。'],privacy:['この体験版のデータについて','お気に入りは、ご利用中のブラウザー内に保存します。相談フォームの入力は送信・保存しません。写真とWebフォントは外部サービスから読み込みます。正式公開時に、運営情報とプライバシーポリシーを掲載します。']};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.save)save(Number(d.save));if(d.plan)detail(Number(d.plan));if(d.planConsult){const p=plans.find(v=>v.id===Number(d.planConsult));consultation(`留学会社${p.company}／${p.title}（サンプル）`)}if(d.consult)consultation(d.consult);if(d.country)countrySelect(d.country);if(d.countryPlans){reset();$('#country').value=d.countryPlans;renderPlans();$('#plans').scrollIntoView()}if(d.theme){reset();theme=d.theme;renderPlans();$('#plans').scrollIntoView()}if('reset'in d)reset();if('close'in d)modal.close();if(d.content){const c=contents[d.content];openModal(`<h2>${c[0]}</h2>${c.slice(1).map(t=>`<p>${t}</p>`).join('')}`)}if(d.article){const a=articles.find(v=>v.id===d.article);openModal(`<img class="modal-img" src="${photo(a.img)}" alt="${a.title}のイメージ"><span class="tag">${a.type}</span><h2>${a.title}</h2><p>${a.body}</p>`)}if(d.journal){document.querySelectorAll('[data-journal]').forEach(v=>v.classList.toggle('active',v===b));journal(d.journal)}if(d.company){reset();companyFilter=d.company;renderPlans();$('#plans').scrollIntoView()}});renderPlans();journal();

